// ---------------------------------------------------------------------------
// Embedded player client: verbatim module sources (63-module closure of the
// crypto 3018 / encoder 9849 / Buffer 5376 modules) + the two VM IIFEs, from
// the public vidfast.vc chunks. Evaluated in node:vm, never eval().

const vm = await import("node:vm");

async function get(url, { as = "text", headers = {}, ua = UA, timeoutMs = 30_000 } = {}) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(url, {
      headers: { "user-agent": ua, ...headers },
      redirect: "follow",
      signal: ctrl.signal,
    });
    if (as === "bytes") {
      if (!res.ok) throw new Error(`HTTP ${res.status} ${url}`);
      return await readPublicBody(res);
    }
    const body = (await readPublicBody(res)).toString('utf8');
    if (!res.ok) throw new Error(`HTTP ${res.status} ${url}: ${body.slice(0, 200)}`);
    return body;
  } finally {
    clearTimeout(t);
  }
}

// Extract the per-title `en` envelope from the SSR player page. The RSC
// flight text escapes quotes (`\"en\":\"...\"`); plain script text is `en":"`.
// Lookbehind rejects keys that merely END in "en" (open, scene, ...).

function extractEn(html) {
  const m = html.match(/(?<![A-Za-z0-9])en\\?":\\?"([A-Za-z0-9_\-]{20,})/);
  return m ? m[1] : null;
}

