// fetch wrapper for the VMs: browser UA + stellar referer, absolute URLs.

function makeVfetch() {
  return async function vfetch(url, init = {}) {
    let u = String(url);
    if (u.includes(" ")) u = u.split(" ").filter(Boolean)[0];
    if (u.startsWith("/")) u = PLAYER + u;
    const headers = {
      "User-Agent": UA,
      "Referer": "https://stellar.rip/",
      "Accept": "*/*",
      "Accept-Language": "en-US,en;q=0.9",
    };
    if (init.headers && typeof init.headers === "object") {
      for (const [k, v] of Object.entries(init.headers)) headers[k] = v;
    }
    const res = await fetch(u, { ...init, headers, redirect: "follow" });
    const buf = await readPublicBody(res);
    const text = buf.toString("utf8");
    return new Proxy(res, {
      get(t, k) {
        if (k === "text") return async () => text;
        if (k === "json") return async () => JSON.parse(text);
        if (k === "arrayBuffer") return async () => buf;
        if (k === "clone") return () => new Response(buf, { status: res.status, headers: res.headers });
        const v = t[k];
        return typeof v === "function" ? v.bind(t) : v;
      },
    });
  };
}

